select id, full_name, email, job_title, hire_date, is_remote, level, lead(salary, 1) over w_grp as next_salary, round(salary / sum(salary) over (partition by job_title, manager_id), 4) as salary_share, ntile(3) over (partition by date_trunc('MONTH', hire_date), level order by salary desc, id) as salary_bucket, dense_rank() over (partition by date_trunc('YEAR', hire_date), manager_id order by salary desc) as salary_dense_rank, lag(salary, 1) over (order by hire_date, id) as prev_salary from employees window w_grp as (order by salary, id);
